<script setup>
import {ref} from 'vue';
import {onBeforeRouteLeave} from 'vue-router';
import {fdate,ftime} from '../../lib/client-info';
import {plainText,saveClientRemark} from '../../lib/client-profile-sections';
import {createClientInfoReader} from '../../api/client-info';
import {useClientSectionData} from '../../composables/useClientSectionData';
const props=defineProps({bundle:Object});const emit=defineEmits(['busy']);
const category=ref('General'),text=ref(''),saving=ref(false),notice=ref(''),saveError=ref('');
const categories=['General','Behaviour','Payment','Medical','Preference','Complaint'];
const {data,loading,error,load}=useClientSectionData(()=>props.bundle,'remarks',async(reader,b)=>{const patient=await reader.doc('Patient',b.pid);b.patient.custom_remarks=patient.custom_remarks||'';return reader.list('Comment',[['reference_doctype','=','Patient'],['reference_name','=',b.pid],['comment_type','in',['Comment','Info']]],['name','content','comment_by','comment_email','owner','creation','comment_type'],300,'creation desc');});
async function save(){if(saving.value)return;saveError.value='';notice.value='';if(text.value.trim().length<3){saveError.value='Write at least 3 characters.';return;}saving.value=true;emit('busy',true);try{const result=await saveClientRemark(createClientInfoReader(),props.bundle,'['+category.value+'] '+text.value.trim());props.bundle.patient.custom_remarks=result.patient.custom_remarks;delete props.bundle.lazy.remarks;text.value='';notice.value=result.warning?'Saved in Patient Remarks. Activity history warning: '+result.warning:'Saved in Patient Remarks and Activity history.';await load(true);}catch(e){saveError.value='Remark not saved/verified: '+e.message;}finally{saving.value=false;emit('busy',false);}}
const note=r=>{const txt=plainText(r.content),match=txt.match(/^\[(\w+)\]\s*/);return {category:match?.[1]||(r.comment_type==='Info'?'System':'General'),text:match?txt.slice(match[0].length):txt};};
onBeforeRouteLeave(()=>!saving.value);
</script>
<template><div class="c3-tab-body"><form class="c3-card c3-note-form" @submit.prevent="save"><header class="c3-card-h"><div><b>📝 Add a remark</b><small>Saved to Patient Remarks (custom_remarks) and Activity history for {{bundle.pid}}.</small></div></header><div class="c3-note-row"><select v-model="category" class="c3-input" data-note-cat :disabled="saving"><option v-for="c in categories" :key="c">{{c}}</option></select><textarea v-model="text" class="c3-input" data-note-text rows="3" maxlength="1000" placeholder="Write a remark for this client" :disabled="saving"></textarea></div><div class="c3-note-foot"><span class="c3-note" data-note-count>{{text.length}} / 1000</span><button type="submit" class="c3-btn c3-btn-primary" data-note-save :disabled="saving">{{saving?'Saving…':'Save remark'}}</button></div><p v-if="saveError" role="alert">{{saveError}}</p><p v-if="notice" role="status">{{notice}}</p></form><section class="c3-card client-saved-remarks"><h4>Saved Patient Remarks</h4><div>{{bundle.patient.custom_remarks||'No Patient remarks saved yet.'}}</div></section><h4 class="c3-h4">Activity history ({{data?.length||0}})</h4><p v-if="loading" role="status">Loading remarks…</p><p v-if="error" role="alert">Could not load remarks: {{error}} <button type="button" class="c3-btn" @click="load(true)">Retry</button></p><div class="c3-remarks"><div v-for="r in data||[]" :key="r.name" class="c3-remark"><div class="c3-remark-h"><span class="c3-pill" :class="'tone-'+(/payment|complaint/i.test(note(r).category)?'warn':/medical/i.test(note(r).category)?'neg':'info')">{{note(r).category}}</span><b>{{r.comment_by||bundle.users[r.owner]||r.owner}}</b><small>{{fdate(r.creation)}} {{ftime(String(r.creation||'').slice(11))}}</small></div><p>{{note(r).text}}</p></div><div v-if="data&&!data.length" class="c3-empty-sm">No remarks found.</div></div></div></template>
<style scoped>.client-saved-remarks{padding:14px;margin:12px 0}.client-saved-remarks h4{margin:0 0 8px;font-size:15px}.client-saved-remarks>div{white-space:pre-wrap;overflow-wrap:anywhere}</style>
